import("context";"testing")
func TestCommonPhysicalTypesAreRealPGColumns(t *testing.T){f:=newFixture(t,nil);fields:=[]Field{{ID:fieldID1,Type:Numeric,Precision:38,Scale:2,Default:&Value{Type:Numeric,Text:"1.24"}},{ID:fieldID2,Type:Date,Default:&Value{Type:Date,Text:"2024-02-29"}},{ID:fieldID3,Type:Timestamp}};r,e:=f.executor.Save(context.Background(),f.request(fields));if e!=nil{t.Fatal("approved physical primitives unavailable",e)};if r.Revision!="1"{t.Fatal("save revision")};var typ string;if e=f.pool.QueryRow(context.Background(),"SELECT format_type(atttypid,atttypmod) FROM pg_attribute WHERE attrelid=to_regclass($1) AND attname=$2",f.namespace+"."+tableName,physicalID("f_",fieldID1)).Scan(&typ);e!=nil||typ!="numeric(38,2)"{t.Fatal("typed numeric oracle",typ,e)}}
